INSERT INTO alg_cases (puzzle, set_slug, position, name, subgroup, setup, sticker, algs)
SELECT '6x6', 'l2c', (item->>'position')::integer, item->>'name', item->>'subgroup', item->>'setup', item->'sticker', item->'algs'
FROM items WHERE NOT EXISTS (SELECT 1 FROM alg_cases WHERE puzzle = '6x6' AND set_slug = 'l2c' AND name = item->>'name');
